+                    bw.newLine();
+                    bw.write("xpack.security.http.ssl.enabled: true");
+                    bw.newLine();
+                    bw.write("xpack.security.http.ssl.keystore.path: " + instantAutoConfigDir.resolve(HTTP_AUTOGENERATED_KEYSTORE_NAME +
