+            password = randomAlphaOfLengthBetween(14, 20);
+            possiblyDecryptKeystore(mockTerminal);
+            mockTerminal.addSecretInput(password);
+            mockTerminal.addSecretInput(password);
+            status = resetElasticPasswordTool.main(new String[] { "-i", "-b" }, mockTerminal);
+        }
